  else{$functionId=(int)($_POST['fonction_id']??0);$title=trim((string)($_POST['intitule']??''));if($functionId<1||$title==='')throw new RuntimeException('La fonction et l’intitulé sont obligatoires.');$values=['mission_principale'=>trim((string)($_POST['mission_principale']??''))?:null,'rattachement_hierarchique'=>trim((string)($_POST['rattachement_hierarchique']??''))?:null];foreach(array_keys($listFields) as $field)$values[$field]=$normalizeList($_POST[$field]??[]);$status=in_array((string)($_POST['statut']??''),['brouillon','active'],true)?(string)$_POST['statut']:'brouillon';if($status==='active'){$q=$pdo->prepare("UPDATE rh_fiches_poste SET statut='archivee',updated_by=? WHERE fonction_id=? AND statut='active' AND id<>?");$q->execute([(int)($_SESSION['user_id']??0),$functionId,$id]);}
