$functions=$pdo->query('SELECT id_fonction id,lib_fonction label FROM fonction ORDER BY lib_fonction')->fetchAll(PDO::FETCH_ASSOC);$edit=null;if($editId){$q=$pdo->prepare('SELECT * FROM rh_fiches_poste WHERE id=?');$q->execute([$editId]);$edit=$q->fetch(PDO::FETCH_ASSOC)?:null;}$rows=$pdo->query('SELECT fp.*,f.lib_fonction fonction_label,(SELECT COUNT(*) FROM personnel p WHERE p.fonction_id=fp.fonction_id AND COALESCE(NULLIF(p.personnel_category,\'\'),\'interne\')=\'interne\' AND (p.date_sortie IS NULL OR p.date_sortie=\'0000-00-00\')) effectif FROM rh_fiches_poste fp JOIN fonction f ON f.id_fonction=fp.fonction_id ORDER BY FIELD(fp.statut,\'active\',\'brouillon\',\'archivee\'),f.lib_fonction,fp.updated_at DESC')->fetchAll(PDO::FETCH_ASSOC);
